use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path};const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-31-g2-denominator-tree176";fn h(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn main(){let p=Path::new(D).join("README.md");let old=fs::read_to_string(&p).unwrap();let mut new=old.clone();for(a,b)in[("9950 X","9950X"),("3(m−1)vector","3(m−1) vector"),("suffixes;174","suffixes; 174"),("9950X,16","9950X, 16"),("usesCPU2;16/32","uses CPU 2; 16/32"),("Root:`","Root: `"),("zero loss, expected","zero loss, expected")]{new=new.replace(a,b);}assert_eq!(old.chars().filter(|c|!c.is_whitespace()).collect::<String>(),new.chars().filter(|c|!c.is_whitespace()).collect::<String>());fs::write(&p,&new).unwrap();let receipt=Path::new(D).join("artifacts/editorial-review.json");let mut v:Value=serde_json::from_slice(&fs::read(&receipt).unwrap()).unwrap();assert_eq!(v["final_sha256"],h(old.as_bytes()));v["first_spacing_pass_sha256"]=json!(h(old.as_bytes()));v["final_sha256"]=json!(h(new.as_bytes()));v["final_spacing_only_pass"]=json!(true);fs::write(receipt,serde_json::to_vec_pretty(&v).unwrap()).unwrap();fs::copy("/home/ubuntu/src/zopro-perf-work/g2-denominator-tree176/final-edit.rs",Path::new(D).join("artifacts/final-edit.rs")).unwrap();let mut paths=vec![];for dir in[Path::new(D).to_path_buf(),Path::new(D).join("artifacts")]{for e in fs::read_dir(dir).unwrap(){let p=e.unwrap().path();if p.is_file()&&p.file_name().unwrap()!="SHA256SUMS"{paths.push(p);}}}paths.sort();let sums=paths.iter().map(|p|format!("{}  {}\n",h(&fs::read(p).unwrap()),p.strip_prefix(D).unwrap().display())).collect::<String>();fs::write(Path::new(D).join("SHA256SUMS"),sums).unwrap();println!("Final prose spacing PASS;all nonwhitespace bytes,raw results and archive hashes unchanged");}
